@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";
@import "@fontsource/poppins/400.css";
@import "@fontsource/poppins/500.css";
@import "@fontsource/poppins/600.css";
@import "@fontsource/poppins/700.css";
@import "@fontsource/poppins/800.css";

@custom-variant dark (&:is(.dark *));

:root {
  --radius: 1.125rem;
  --background: #efeff4;
  --foreground: #000000;
  --card: #ffffff;
  --card-foreground: #000000;
  --popover: #ffffff;
  --popover-foreground: #000000;
  --primary: #007aff;
  --primary-foreground: #ffffff;
  --secondary: #e5e5ea;
  --secondary-foreground: #000000;
  --muted: #e5e5ea;
  --muted-foreground: #8e8e93;
  --accent: rgba(0, 122, 255, 0.12);
  --accent-foreground: #007aff;
  --destructive: #ff3b30;
  --destructive-foreground: #ffffff;
  --success: #34c759;
  --warning: #ff9500;
  --navy: #1c1c1e;
  --navy-foreground: #ffffff;
  --border: rgba(60, 60, 67, 0.18);
  --input: rgba(60, 60, 67, 0.18);
  --ring: #007aff;
  --chart-1: #007aff;
  --chart-2: #34c759;
  --chart-3: #ff9500;
  --chart-4: #af52de;
  --chart-5: #ff2d55;
  --sidebar: #f7f7f8;
  --sidebar-foreground: #000000;
  --sidebar-primary: #007aff;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: rgba(0, 122, 255, 0.12);
  --sidebar-accent-foreground: #007aff;
  --sidebar-border: rgba(60, 60, 67, 0.12);
  --sidebar-ring: #007aff;
}

.dark {
  --background: #000000;
  --foreground: #ffffff;
  --card: #1c1c1d;
  --card-foreground: #ffffff;
  --popover: #1c1c1d;
  --popover-foreground: #ffffff;
  --primary: #0a84ff;
  --primary-foreground: #ffffff;
  --secondary: #2c2c2e;
  --secondary-foreground: #ffffff;
  --muted: #2c2c2e;
  --muted-foreground: #8e8e93;
  --accent: rgba(10, 132, 255, 0.18);
  --accent-foreground: #70b5ff;
  --destructive: #ff453a;
  --destructive-foreground: #ffffff;
  --success: #30d158;
  --warning: #ffd60a;
  --navy: #2c2c2e;
  --navy-foreground: #ffffff;
  --border: rgba(255, 255, 255, 0.15);
  --input: rgba(255, 255, 255, 0.15);
  --ring: #0a84ff;
  --chart-1: #0a84ff;
  --chart-2: #30d158;
  --chart-3: #ffd60a;
  --chart-4: #bf5af2;
  --chart-5: #ff375f;
  --sidebar: #121212;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #0a84ff;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: rgba(10, 132, 255, 0.18);
  --sidebar-accent-foreground: #70b5ff;
  --sidebar-border: rgba(255, 255, 255, 0.12);
  --sidebar-ring: #0a84ff;
}

@theme inline {
  --radius-sm: calc(var(--radius) - 6px);
  --radius-md: calc(var(--radius) - 3px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --radius-2xl: calc(var(--radius) + 8px);
  --radius-3xl: calc(var(--radius) + 14px);
  --radius-4xl: calc(var(--radius) + 20px);
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-navy: var(--navy);
  --color-navy-foreground: var(--navy-foreground);
  --shadow-soft: 0 1px 3px rgba(0, 0, 0, 0.05), 0 10px 15px -5px rgba(0, 0, 0, 0.04);
  --shadow-float: 0 12px 36px rgba(0, 0, 0, 0.14), 0 4px 12px rgba(0, 0, 0, 0.06);
  --shadow-ios-thumb: 0 0.5px 4px rgba(0, 0, 0, 0.12), 0 6px 13px rgba(0, 0, 0, 0.12);
  --font-heading: var(--font-sans);
  --tracking-tight: -0.015em;
  --tracking-tighter: -0.025em;
  --font-sans: 'Poppins', -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "SF UI Text", system-ui, "Helvetica Neue", Helvetica, Arial, sans-serif;
  --color-sidebar-ring: var(--sidebar-ring);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar: var(--sidebar);
  --color-chart-5: var(--chart-5);
  --color-chart-4: var(--chart-4);
  --color-chart-3: var(--chart-3);
  --color-chart-2: var(--chart-2);
  --color-chart-1: var(--chart-1);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply antialiased bg-background text-foreground;
  }
  html {
    @apply font-sans;
  }
  h1,
  h2,
  h3,
  h4 {
    @apply tracking-tight font-semibold;
  }
}

*{
    scrollbar-width: none;
    &::-webkit-scrollbar {
      display: none;
      opacity: 0;
    }
}
